package com.personal.meditation;
import org.junit.Test;import static org.junit.Assert.*;
public class SessionClockTest {
 @Test public void prepHasTwoShortPulsesThenLongAndBellAtThirty(){SessionClock c=new SessionClock();c.start(1000,600000);assertNull(c.poll(27999));assertEquals(SessionClock.Cue.SHORT_ONE,c.poll(28000));assertEquals(SessionClock.Cue.SHORT_TWO,c.poll(29000));assertEquals(SessionClock.Cue.LONG,c.poll(30000));assertEquals("preparing",c.phase(30999));assertEquals(SessionClock.Cue.START,c.poll(31000));assertEquals("meditating",c.phase(31000));assertEquals(600000,c.remaining(31000));}
 @Test public void tenMinutesHasExactlyThreeQuarterChimesAndOneEnd(){SessionClock c=new SessionClock();c.start(0,600000);assertEquals(SessionClock.Cue.START,c.poll(30000));assertNull(c.poll(179999));assertEquals(SessionClock.Cue.INTERVAL,c.poll(180000));assertEquals(SessionClock.Cue.INTERVAL,c.poll(330000));assertEquals(SessionClock.Cue.INTERVAL,c.poll(480000));assertEquals(SessionClock.Cue.END,c.poll(630000));assertEquals("finished",c.phase(630000));assertEquals(0,c.remaining(630000));assertNull(c.poll(900000));}
 @Test public void pauseAndResumeKeepExactRemainingTimesAndDoNotRepeatCues(){SessionClock c=new SessionClock();c.start(0,60000);c.poll(27000);c.pause(27500);assertEquals("paused",c.phase(100000));assertEquals(2500,c.remaining(100000));assertNull(c.poll(100000));c.resume(100000);assertEquals(SessionClock.Cue.SHORT_TWO,c.poll(100500));assertEquals(SessionClock.Cue.LONG,c.poll(101500));assertEquals(SessionClock.Cue.START,c.poll(102500));assertEquals(60000,c.remaining(102500));c.pause(110000);c.resume(210000);assertEquals(52500,c.remaining(210000));assertEquals(SessionClock.Cue.INTERVAL,c.poll(217500));}
 @Test public void delayedRefreshDoesNotShiftDeadlinesOrBurstOldCues(){SessionClock c=new SessionClock();c.start(0,60000);assertEquals(SessionClock.Cue.START,c.poll(31000));assertEquals(59000,c.remaining(31000));assertEquals(SessionClock.Cue.INTERVAL,c.poll(60000));assertNull(c.poll(60000));assertEquals(SessionClock.Cue.END,c.poll(90001));}
 @Test public void endResetAndNewSessionHaveNoStaleEvents(){SessionClock c=new SessionClock();c.start(0,60000);c.poll(90000);c.stop();assertEquals("idle",c.phase(100000));assertNull(c.poll(100000));c.start(100000,120000);assertEquals(30000,c.remaining(100000));assertNull(c.poll(126999));assertEquals(SessionClock.Cue.SHORT_ONE,c.poll(127000));}
 @Test public void durationsAreBounded(){for(long ms:new long[]{0,59999,14400001})try{new SessionClock().start(0,ms);fail();}catch(IllegalArgumentException expected){}SessionClock c=new SessionClock();c.start(0,14400000);assertEquals(14400000,c.duration());}
 @Test public void schedulingTargetsCueDeadlinesInsteadOfAccumulatingPollDelays(){SessionClock c=new SessionClock();c.start(1000,600000);assertEquals(1000,c.nextDelay(1000));assertEquals(1,c.nextDelay(27999));assertEquals(SessionClock.Cue.SHORT_ONE,c.poll(28000));assertEquals(750,c.nextDelay(28250));assertEquals(SessionClock.Cue.SHORT_TWO,c.poll(29000));assertEquals(1,c.nextDelay(29999));assertEquals(SessionClock.Cue.LONG,c.poll(30000));assertEquals(SessionClock.Cue.START,c.poll(31000));assertEquals(1,c.nextDelay(180999));assertEquals(SessionClock.Cue.INTERVAL,c.poll(181000));c.pause(181100);assertEquals(1000,c.nextDelay(999999));c.resume(1000000);assertEquals(1000,c.nextDelay(1000000));}

 @Test public void everyDivisionCountHasExactEvenCuesAndOnlyOneEnd(){for(int divisions=1;divisions<=6;divisions++){
  SessionClock c=new SessionClock();long duration=480000;c.start(1234,duration,divisions);
  assertEquals(SessionClock.Cue.START,c.poll(1234+SessionClock.PREP));
  for(int part=1;part<divisions;part++){long due=1234+SessionClock.PREP+duration*part/divisions;assertNull(c.poll(due-1));assertEquals(SessionClock.Cue.INTERVAL,c.poll(due));assertEquals(part+1,c.interval(due));assertNull(c.poll(due));}
  assertNull(c.poll(1234+SessionClock.PREP+duration-1));assertEquals(SessionClock.Cue.END,c.poll(1234+SessionClock.PREP+duration));assertNull(c.poll(9999999));
 }}
 @Test public void invalidIntervalCountsCannotReplaceAnExistingSession(){SessionClock c=new SessionClock();c.start(1000,480000,3);for(int count:new int[]{0,7,20})try{c.start(2000,60000,count);fail();}catch(IllegalArgumentException expected){}assertEquals(480000,c.duration());assertEquals(29000,c.remaining(2000));}
 @Test public void sixthsKeepDeadlinesAcrossPausesAndSkipMissedCues(){SessionClock c=new SessionClock();c.start(0,60000,6);c.poll(30000);c.pause(35000);c.resume(135000);assertNull(c.poll(139999));assertEquals(SessionClock.Cue.INTERVAL,c.poll(140000));assertEquals(SessionClock.Cue.INTERVAL,c.poll(170001));assertNull(c.poll(170001));assertEquals(SessionClock.Cue.END,c.poll(190000));}

 @Test public void customPreparationMovesAllDeadlinesWithoutChangingMeditationLength(){SessionClock c=new SessionClock();c.start(1000,480000,4,10000);assertEquals(10000,c.remaining(1000));assertNull(c.poll(7999));assertEquals(SessionClock.Cue.SHORT_ONE,c.poll(8000));assertEquals(SessionClock.Cue.SHORT_TWO,c.poll(9000));assertEquals(SessionClock.Cue.LONG,c.poll(10000));assertEquals(SessionClock.Cue.START,c.poll(11000));assertEquals(480000,c.remaining(11000));assertEquals(SessionClock.Cue.INTERVAL,c.poll(131000));assertEquals(SessionClock.Cue.END,c.poll(491000));}
 @Test public void shortAndZeroCountdownsOnlyPlayCuesThatFit(){SessionClock c=new SessionClock();c.start(0,60000,1,0);assertEquals("meditating",c.phase(0));assertEquals(60000,c.remaining(0));assertEquals(SessionClock.Cue.START,c.poll(0));assertNull(c.poll(0));assertEquals(SessionClock.Cue.END,c.poll(60000));c.start(0,60000,1,1000);assertEquals(SessionClock.Cue.LONG,c.poll(0));assertEquals(SessionClock.Cue.START,c.poll(1000));c.start(0,60000,1,2000);assertEquals(SessionClock.Cue.SHORT_TWO,c.poll(0));assertEquals(SessionClock.Cue.LONG,c.poll(1000));assertEquals(SessionClock.Cue.START,c.poll(2000));}
 @Test public void customCountdownPauseAndLimitsStayExact(){SessionClock c=new SessionClock();c.start(0,60000,3,5000);c.poll(0);c.pause(1000);assertEquals(4000,c.remaining(90000));c.resume(90000);assertEquals(SessionClock.Cue.START,c.poll(94000));assertEquals(SessionClock.Cue.INTERVAL,c.poll(114000));for(long invalid:new long[]{-1,300001})try{c.start(0,60000,1,invalid);fail();}catch(IllegalArgumentException expected){}c.start(0,60000,1,300000);assertEquals(300000,c.remaining(0));}
}
